effect.shader:
void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    vec2 p = (acScreenNorm - 0.5) * scale;
    float t = acTime * speed;
    float v = sin(p.x + t);
    v += sin(p.y + t * 1.3);
    v += sin((p.x + p.y) * 0.7 + t * 0.7);
    v += sin(length(p) * 2.0 - t * 2.0);
    float a = v / 4.0 * 0.5 + 0.5;

    vec3 plasma;
    if (a < 0.5) plasma = mix(c1.rgb, c2.rgb, a * 2.0);
    else         plasma = mix(c2.rgb, c3.rgb, (a - 0.5) * 2.0);

    fragColor = vec4(mix(orig.rgb, plasma, intensity), orig.a);
}
